import{_ as t,a as o,o as r,a6 as a}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Customer Groups","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/customers/groups/index.md","filePath":"api/rest-api/admin/customers/groups/index.md","lastUpdated":1787725411000}'),s={name:"api/rest-api/admin/customers/groups/index.md"};function d(i,e,n,u,l,c){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="customer-groups" tabindex="-1">Customer Groups <a class="header-anchor" href="#customer-groups" aria-label="Permalink to &quot;Customer Groups&quot;">​</a></h1><p>The Customer Groups menu manages the named groups customers are sorted into — such as <em>general</em>, <em>wholesale</em>, and <em>guest</em>. A group is the lever that drives group-specific pricing and promotions: every customer belongs to exactly one group, and catalog/cart rules can target a group. It mirrors the admin <strong>Customers → Groups</strong> screen.</p><h2 id="what-a-group-holds" tabindex="-1">What a group holds <a class="header-anchor" href="#what-a-group-holds" aria-label="Permalink to &quot;What a group holds&quot;">​</a></h2><p>A group has a <code>code</code> (a stable identifier) and a <code>name</code> (the display label), plus a flag marking whether it is a built-in system group or an admin-created one. The single-group <code>GET</code> also returns how many customers belong to it.</p><h2 id="system-groups-vs-user-defined-groups" tabindex="-1">System groups vs. user-defined groups <a class="header-anchor" href="#system-groups-vs-user-defined-groups" aria-label="Permalink to &quot;System groups vs. user-defined groups&quot;">​</a></h2><p>The store ships with built-in <strong>system groups</strong> (e.g. <em>general</em>, <em>wholesale</em>, <em>guest</em>) that other parts of the store rely on. These are protected:</p><ul><li>Their <code>code</code> cannot be changed and they cannot be re-flagged — only the <code>name</code> is editable.</li><li>They cannot be deleted.</li></ul><p>Groups you create through this menu are <strong>user-defined</strong> and fully editable.</p><h2 id="delete-guards" tabindex="-1">Delete guards <a class="header-anchor" href="#delete-guards" aria-label="Permalink to &quot;Delete guards&quot;">​</a></h2><p>A group cannot be deleted when:</p><ul><li>It is a <strong>system group</strong>, or</li><li>It is <strong>in use</strong> — one or more customers still belong to it. Re-assign those customers to another group first.</li></ul><p>In a single delete the guard returns a <code>400</code>; in mass delete the blocked id is reported under <code>skipped</code> while the rest of the batch proceeds.</p><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>code</code></td><td>Stable group identifier. Unique; immutable on system groups.</td></tr><tr><td><code>name</code></td><td>Display label.</td></tr><tr><td><code>isUserDefined</code></td><td>Whether the group was created by an admin (vs. a built-in system group).</td></tr><tr><td><code>customersCount</code></td><td>Number of customers in the group. <strong>Detail-only.</strong></td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>Timestamps.</td></tr></tbody></table><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="./list.html">List Groups</a></td><td><code>GET /api/admin/customers/groups</code></td></tr><tr><td><a href="./detail.html">Group Detail</a></td><td><code>GET /api/admin/customers/groups/{id}</code></td></tr><tr><td><a href="./create.html">Create Group</a></td><td><code>POST /api/admin/customers/groups</code></td></tr><tr><td><a href="./update.html">Update Group</a></td><td><code>PUT /api/admin/customers/groups/{id}</code></td></tr><tr><td><a href="./delete.html">Delete Group</a></td><td><code>DELETE /api/admin/customers/groups/{id}</code></td></tr><tr><td><a href="./mass-delete.html">Mass Delete</a></td><td><code>POST /api/admin/customers/groups/mass-delete</code></td></tr></tbody></table><p>Permissions: <code>customers.groups.create</code> / <code>.edit</code> / <code>.delete</code>.</p>',17)]))}const m=t(s,[["render",d]]);export{h as __pageData,m as default};
